// Adjusts the config.toml generated by `supabase init` for the end-to-end run:
// app URL, email confirmation, sign-up hook, branded templates and security notifications.
// Usage: node e2e/configure-supabase.mjs <path to config.toml> <app port>
import { readFileSync, writeFileSync } from "node:fs"

const [configPath, appPort] = process.argv.slice(2)
const appUrl = `http://localhost:${appPort}`
let lines = readFileSync(configPath, "utf8").split("\n")

// Sets `key = value` inside a [section] (or at the top of the file when section is null).
function setKey(section, key, value) {
  let start = 0
  if (section) {
    start = lines.findIndex((line) => line.trim() === `[${section}]`)
    if (start === -1) throw new Error(`Section [${section}] not found in config.toml`)
    start += 1
  }
  for (let i = start; i < lines.length; i++) {
    if (section && /^\[/.test(lines[i])) break
    if (new RegExp(`^${key}\\s*=`).test(lines[i])) {
      lines[i] = `${key} = ${value}`
      return
    }
  }
  throw new Error(`Key ${key} not found in [${section ?? "root"}]`)
}

setKey(null, "project_id", '"cijj-e2e"')
setKey("auth", "site_url", `"${appUrl}"`)
setKey("auth", "additional_redirect_urls", `["${appUrl}/auth/**"]`)
setKey("auth.email", "enable_confirmations", "true")
setKey("auth.rate_limit", "email_sent", "100")

// Template paths are relative to the project root; notification paths to the supabase folder.
const templates = {
  confirmation: ["Confirma tu cuenta de la red de miembros", "confirm-signup"],
  recovery: ["Crea una nueva contraseña", "reset-password"],
  invite: ["Te invitaron a Ingenieros Jóvenes de Jalisco", "invite-user"],
  magic_link: ["Tu enlace para entrar a la red de miembros", "magic-link"],
  email_change: ["Confirma tu nuevo correo", "change-email"],
  reauthentication: ["Tu código de verificación", "reauthentication"],
}
const notifications = {
  password_changed: ["Tu contraseña cambió", "password-changed"],
  email_changed: ["El correo de tu cuenta cambió", "email-changed"],
  identity_linked: ["Se agregó una forma de entrar a tu cuenta", "sign-in-method-linked"],
  identity_unlinked: ["Se quitó una forma de entrar a tu cuenta", "sign-in-method-removed"],
}

lines.push(
  "",
  "# ---- Added by e2e/configure-supabase.mjs ----",
  "[auth.hook.before_user_created]",
  "enabled = true",
  'uri = "pg-functions://postgres/public/hook_only_authorized_emails"',
  ...Object.entries(templates).flatMap(([name, [subject, file]]) => [
    "",
    `[auth.email.template.${name}]`,
    `subject = "${subject}"`,
    `content_path = "./supabase/templates/${file}.html"`,
  ]),
  ...Object.entries(notifications).flatMap(([name, [subject, file]]) => [
    "",
    `[auth.email.notification.${name}]`,
    "enabled = true",
    `subject = "${subject}"`,
    `content_path = "./templates/${file}.html"`,
  ])
)

writeFileSync(configPath, lines.join("\n"))
